function StatCard({ label, value, tone, icon: Icon }) {
  const tones = {
    neutral: { text: "text-[#14283A]", bg: "#EAF0F5", fg: "#14283A", bar: "#14283A" },
    warn: { text: "text-[#C4791E]", bg: "#FBEAD9", fg: "#C4791E", bar: "#C9A050" },
    ok: { text: "text-[#2C6B45]", bg: "#E3EEE6", fg: "#2C6B45", bar: "#2C6B45" },
  };
  const t = tones[tone || "neutral"];
  return (
    <div className="relative bg-white border border-[#E4E1D6] rounded-xl px-5 py-4 flex-1 min-w-[150px] overflow-hidden shadow-[0_1px_2px_rgba(20,40,58,0.04)] hover:shadow-[0_4px_14px_rgba(20,40,58,0.08)] transition-shadow">
      <span className="absolute top-0 left-0 w-full h-[3px]" style={{ backgroundColor: t.bar }} />
      <div className="flex items-start justify-between">
        <p className="text-[12px] text-[#8A8578]">{label}</p>
        {Icon && (
          <div
            className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0"
            style={{ backgroundColor: t.bg, color: t.fg }}
          >
            <Icon size={15} />
          </div>
        )}
      </div>
      <p className={`text-[28px] font-semibold mt-1 tracking-tight ${t.text}`}>{value}</p>
    </div>
  );
}

function DimensionDivider() {
  return (
    <div className="flex items-center gap-1.5 my-6 select-none" aria-hidden="true">
      <span className="w-px h-2 bg-[#D8C08A]" />
      <span className="flex-1 h-px bg-gradient-to-r from-[#D8C08A] via-[#E4D6B0] to-transparent" />
      <span className="w-1 h-1 rounded-full bg-[#C9A050]" />
    </div>
  );
}

function EstadoDot({ estado }) {
  const map = { Aberta: "#C4791E", "Em correção": "#C9A050", Fechada: "#2C6B45" };
  return (
    <span className="inline-flex items-center gap-1.5 text-[12px] font-medium" style={{ color: map[estado] }}>
      <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: map[estado] }} />
      {estado}
    </span>
  );
}

function AreaEstadoTag({ estado }) {
  const map = {
    Concluído: { bg: "#E3EEE6", fg: "#2C6B45" },
    "Em andamento": { bg: "#EAF0F7", fg: "#2E5C8A" },
    Atenção: { bg: "#FBEAD9", fg: "#8A4A17" },
    Atrasado: { bg: "#FBE3E1", fg: "#B0402F" },
    Pendente: { bg: "#EDEBE2", fg: "#8A8578" },
  };
  const s = map[estado] || map["Pendente"];
  return (
    <span className="text-[11px] font-medium px-2 py-0.5 rounded" style={{ backgroundColor: s.bg, color: s.fg }}>
      {estado}
    </span>
  );
}

function SeveridadeTag({ nivel }) {
  const map = {
    Alta: { bg: "#FBE3E1", fg: "#B0402F" },
    Média: { bg: "#FBEAD9", fg: "#8A4A17" },
    Baixa: { bg: "#EDEBE2", fg: "#8A8578" },
  };
  const s = map[nivel] || map["Baixa"];
  return (
    <span className="text-[11px] font-medium px-2 py-0.5 rounded" style={{ backgroundColor: s.bg, color: s.fg }}>
      {nivel}
    </span>
  );
}

function PageHeader({ title, subtitle, action }) {
  return (
    <div className="flex items-center justify-between mb-5">
      <div className="flex items-start gap-2.5">
        <span className="w-[3px] h-8 bg-gradient-to-b from-[#C9A050] to-[#E4D6B0] rounded-full mt-0.5 shrink-0" />
        <div>
          <h1 className="text-[19px] font-semibold text-[#14283A] tracking-tight">{title}</h1>
          {subtitle && <p className="text-[13px] text-[#8A8578]">{subtitle}</p>}
        </div>
      </div>
      {action}
    </div>
  );
}

