const CONTAS_CLIENTE_DEMO = [
  { nome: "Ana Ferreira", email: "ana.ferreira@email.com", password: "demo123", obraId: 1 },
];

function EcraLoginCliente({ contas, onEntrar, onIrRegisto }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [erro, setErro] = useState("");

  const entrar = () => {
    const conta = contas.find((c) => c.email === email && c.password === password);
    if (!conta) {
      setErro("Email ou palavra-passe incorretos.");
      return;
    }
    setErro("");
    onEntrar(conta);
  };

  return (
    <div className="max-w-sm mx-auto bg-white border border-[#E4E1D6] rounded-xl overflow-hidden">
      <div className="bg-[#14283A] px-6 py-6 flex flex-col items-center">
        <img src={LOGO_SRC} alt="Fiscalis" className="h-10 w-auto mb-2" />
        <p className="text-white text-[13px] font-medium">Portal do Cliente</p>
      </div>
      <div className="p-6">
        <label className="text-[12px] font-medium text-[#4A4740] block mb-1">Email</label>
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="o-teu-email@exemplo.com"
          className="w-full px-3 py-2 rounded-lg border border-[#DEDBD2] text-[13px] bg-white focus:outline-none focus:border-[#14283A] mb-3"
        />
        <label className="text-[12px] font-medium text-[#4A4740] block mb-1">Palavra-passe</label>
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="••••••••"
          className="w-full px-3 py-2 rounded-lg border border-[#DEDBD2] text-[13px] bg-white focus:outline-none focus:border-[#14283A]"
        />
        {erro && <p className="text-[12px] text-[#B0402F] mt-2">{erro}</p>}

        <button onClick={entrar} className="w-full mt-4 py-2.5 rounded-lg bg-[#14283A] text-white text-[13px] font-medium">
          Entrar
        </button>
        <p className="text-[12px] text-[#8A8578] text-center mt-3">
          Ainda não tens conta?{" "}
          <button onClick={onIrRegisto} className="text-[#14283A] font-medium underline underline-offset-2">
            Criar conta
          </button>
        </p>
        <p className="text-[11px] text-[#B4AF9F] text-center mt-3">
          Conta de demonstração: {CONTAS_CLIENTE_DEMO[0].email} / {CONTAS_CLIENTE_DEMO[0].password}
        </p>
      </div>
    </div>
  );
}

function EcraRegistoCliente({ onCriarConta, onIrLogin }) {
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [obraId, setObraId] = useState(OBRAS[0].id);
  const [password, setPassword] = useState("");
  const [confirmar, setConfirmar] = useState("");
  const [erro, setErro] = useState("");

  const criar = () => {
    if (!nome.trim() || !email.trim() || !password) {
      setErro("Preenche todos os campos.");
      return;
    }
    if (password !== confirmar) {
      setErro("As palavras-passe não coincidem.");
      return;
    }
    setErro("");
    onCriarConta({ nome, email, password, obraId: Number(obraId) });
  };

  return (
    <div className="max-w-sm mx-auto bg-white border border-[#E4E1D6] rounded-xl overflow-hidden">
      <div className="bg-[#14283A] px-6 py-6 flex flex-col items-center">
        <img src={LOGO_SRC} alt="Fiscalis" className="h-10 w-auto mb-2" />
        <p className="text-white text-[13px] font-medium">Criar conta de cliente</p>
      </div>
      <div className="p-6">
        <label className="text-[12px] font-medium text-[#4A4740] block mb-1">Nome</label>
        <input
          value={nome}
          onChange={(e) => setNome(e.target.value)}
          className="w-full px-3 py-2 rounded-lg border border-[#DEDBD2] text-[13px] bg-white focus:outline-none focus:border-[#14283A] mb-3"
        />
        <label className="text-[12px] font-medium text-[#4A4740] block mb-1">Email</label>
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="w-full px-3 py-2 rounded-lg border border-[#DEDBD2] text-[13px] bg-white focus:outline-none focus:border-[#14283A] mb-3"
        />
        <label className="text-[12px] font-medium text-[#4A4740] block mb-1">A tua obra</label>
        <select
          value={obraId}
          onChange={(e) => setObraId(e.target.value)}
          className="w-full px-3 py-2 rounded-lg border border-[#DEDBD2] text-[13px] bg-white mb-3"
        >
          {OBRAS.map((o) => (
            <option key={o.id} value={o.id}>
              {o.nome}
            </option>
          ))}
        </select>
        <label className="text-[12px] font-medium text-[#4A4740] block mb-1">Palavra-passe</label>
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className="w-full px-3 py-2 rounded-lg border border-[#DEDBD2] text-[13px] bg-white focus:outline-none focus:border-[#14283A] mb-3"
        />
        <label className="text-[12px] font-medium text-[#4A4740] block mb-1">Confirmar palavra-passe</label>
        <input
          type="password"
          value={confirmar}
          onChange={(e) => setConfirmar(e.target.value)}
          className="w-full px-3 py-2 rounded-lg border border-[#DEDBD2] text-[13px] bg-white focus:outline-none focus:border-[#14283A]"
        />
        {erro && <p className="text-[12px] text-[#B0402F] mt-2">{erro}</p>}

        <button onClick={criar} className="w-full mt-4 py-2.5 rounded-lg bg-[#14283A] text-white text-[13px] font-medium">
          Criar conta
        </button>
        <p className="text-[12px] text-[#8A8578] text-center mt-3">
          Já tens conta?{" "}
          <button onClick={onIrLogin} className="text-[#14283A] font-medium underline underline-offset-2">
            Entrar
          </button>
        </p>
      </div>
    </div>
  );
}

function PortalClienteView() {
  const [contas, setContas] = useState(CONTAS_CLIENTE_DEMO);
  const [ecra, setEcra] = useState("login"); // login | registo | portal
  const [sessao, setSessao] = useState(null);

  const criarConta = (dados) => {
    setContas((prev) => [...prev, dados]);
    setSessao(dados);
    setEcra("portal");
  };

  const terminarSessao = () => {
    setSessao(null);
    setEcra("login");
  };

  if (ecra !== "portal" || !sessao) {
    return (
      <>
        <PageHeader title="Portal do Cliente" subtitle="Ecrã de acesso que o cliente vê ao entrar" />
        {ecra === "login" ? (
          <EcraLoginCliente
            contas={contas}
            onEntrar={(conta) => {
              setSessao(conta);
              setEcra("portal");
            }}
            onIrRegisto={() => setEcra("registo")}
          />
        ) : (
          <EcraRegistoCliente onCriarConta={criarConta} onIrLogin={() => setEcra("login")} />
        )}
      </>
    );
  }

  const obraId = sessao.obraId;
  const obra = OBRAS.find((o) => o.id === obraId) || OBRAS[0];
  const docs = DOCUMENTOS_POR_OBRA[obraId] || [];
  const ncsObra = NC_TODAS.filter((n) => n.obra === obra.nome);
  const relatoriosObra = RELATORIOS.filter((r) => r.obra === obra.nome);

  return (
    <>
      <PageHeader title="Portal do Cliente" subtitle={`Sessão iniciada como ${sessao.nome}`} />

      {/* Simulação da janela do portal */}
      <div className="bg-white border border-[#E4E1D6] rounded-xl overflow-hidden max-w-3xl">
        <div className="bg-[#14283A] px-6 py-5 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <img src={LOGO_SRC} alt="Fiscalis" className="h-7 w-auto" />
            <span className="text-white text-[13px] font-medium">Fiscalis Engenharia</span>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-[11px] text-[#9FB0BF] flex items-center gap-1">
              <User size={12} /> {sessao.nome}
            </span>
            <button onClick={terminarSessao} className="text-[11px] text-[#9FB0BF] hover:text-white underline underline-offset-2">
              Sair
            </button>
          </div>
        </div>

        <div className="p-6">
          <p className="text-[16px] font-semibold text-[#14283A]">{obra.nome}</p>
          <p className="text-[12px] text-[#8A8578] flex items-center gap-1 mt-1">
            <MapPin size={11} /> {obra.local} · Início: {obra.inicio}
          </p>

          <div className="mt-4 flex items-center gap-3">
            <div className="flex-1 h-2 bg-[#EDEBE2] rounded-full overflow-hidden">
              <div className="h-full bg-[#C9A050] rounded-full" style={{ width: `${obra.progresso}%` }} />
            </div>
            <span className="text-[13px] font-mono text-[#14283A] font-medium">{obra.progresso}%</span>
          </div>

          <div className="grid grid-cols-2 gap-4 mt-6">
            <div>
              <p className="text-[12px] font-medium text-[#4A4740] mb-2">Relatórios disponíveis</p>
              <div className="space-y-1.5">
                {relatoriosObra.length === 0 && <p className="text-[12px] text-[#8A8578]">Ainda sem relatórios.</p>}
                {relatoriosObra.map((r) => (
                  <div key={r.id} className="flex items-center justify-between text-[12px] bg-[#F5F4EF] rounded-lg px-3 py-2">
                    <span className="text-[#1F1D19]">{r.data}</span>
                    <ExternalLink size={12} className="text-[#8A8578]" />
                  </div>
                ))}
              </div>
            </div>

            <div>
              <p className="text-[12px] font-medium text-[#4A4740] mb-2">Não conformidades</p>
              <div className="space-y-1.5">
                {ncsObra.length === 0 && <p className="text-[12px] text-[#8A8578]">Sem registos.</p>}
                {ncsObra.map((n) => (
                  <div key={n.id} className="flex items-center justify-between text-[12px] bg-[#F5F4EF] rounded-lg px-3 py-2">
                    <span className="text-[#1F1D19] truncate max-w-[160px]">{n.descricao}</span>
                    <EstadoDot estado={n.estado} />
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="mt-6">
            <p className="text-[12px] font-medium text-[#4A4740] mb-2">Documentos do projeto</p>
            <div className="flex flex-wrap gap-2">
              {docs.length === 0 && <p className="text-[12px] text-[#8A8578]">Sem documentos.</p>}
              {docs.map((d) => (
                <span key={d.id} className="text-[11px] text-[#4A4740] bg-[#F5F4EF] border border-[#E4E1D6] rounded px-2 py-1">
                  {d.nome}
                </span>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-3xl mt-3 flex items-start gap-2 text-[12px] text-[#8A8578] bg-[#FBEAD9] border border-[#EFCBA2] rounded-lg px-3 py-2.5">
        <ShieldCheck size={14} className="text-[#8A4A17] mt-0.5 shrink-0" />
        As contas aqui só existem enquanto esta app estiver aberta — é uma demonstração do fluxo. Para
        contas reais e seguras (palavras-passe encriptadas, recuperação de acesso, sessões persistentes),
        precisamos de ligar isto a um backend com base de dados, que é o próximo passo depois do GitHub/Vercel.
      </div>
    </>
  );
}

