function ConfiguracoesView() {
  const [itens, setItens] = useState(CHECKLIST_CONFIG);
  const [novoItem, setNovoItem] = useState("");
  const [novaEspecialidade, setNovaEspecialidade] = useState("Estrutura");

  const adicionar = () => {
    if (!novoItem.trim()) return;
    setItens((prev) => [...prev, { especialidade: novaEspecialidade, item: novoItem.trim() }]);
    setNovoItem("");
  };

  const remover = (idx) => setItens((prev) => prev.filter((_, i) => i !== idx));

  return (
    <>
      <PageHeader title="Configurações" subtitle="Dados do diretor de fiscalização e preferências da app" />

      <div className="bg-white border border-[#E4E1D6] rounded-xl p-5 max-w-md flex items-center gap-4 mb-6">
        <div className="w-14 h-14 rounded-full bg-[#14283A] text-white flex items-center justify-center text-[16px] font-medium">
          PM
        </div>
        <div>
          <p className="text-[14px] font-medium text-[#1F1D19]">Pedro Miguel Ribeiro Melro</p>
          <p className="text-[12px] text-[#8A8578]">Eng.º Civil · Cédula Profissional n.º 82160</p>
          <p className="text-[12px] text-[#8A8578]">Ordem dos Engenheiros · Região Centro</p>
        </div>
      </div>

      <p className="text-[13px] font-medium text-[#4A4740] mb-2">Checklist de visita (configurável)</p>
      <div className="bg-white border border-[#E4E1D6] rounded-xl max-w-xl mb-3 divide-y divide-[#F2F0E8]">
        {itens.map((c, i) => (
          <div key={i} className="flex items-center justify-between px-4 py-2.5">
            <div>
              <span className="text-[11px] text-[#8A8578] font-mono mr-2">{c.especialidade}</span>
              <span className="text-[13px] text-[#1F1D19]">{c.item}</span>
            </div>
            <button onClick={() => remover(i)} className="text-[#B0402F] shrink-0">
              <Trash2 size={14} />
            </button>
          </div>
        ))}
      </div>
      <div className="flex gap-2 max-w-xl mb-8">
        <select
          value={novaEspecialidade}
          onChange={(e) => setNovaEspecialidade(e.target.value)}
          className="px-2 py-2 rounded-lg border border-[#DEDBD2] text-[12px] bg-white"
        >
          {["Estrutura", "Águas e esgotos", "Eletricidade", "Segurança", "Acabamentos", "Térmica e acústica"].map((e) => (
            <option key={e} value={e}>
              {e}
            </option>
          ))}
        </select>
        <input
          value={novoItem}
          onChange={(e) => setNovoItem(e.target.value)}
          placeholder="Novo item de verificação"
          className="flex-1 px-3 py-2 rounded-lg border border-[#DEDBD2] text-[13px] bg-white"
        />
        <button onClick={adicionar} className="px-3 py-2 rounded-lg bg-[#14283A] text-white text-[12px] font-medium">
          Adicionar
        </button>
      </div>

      <p className="text-[13px] font-medium text-[#4A4740] mb-2">Em preparação</p>
      <div className="max-w-xl space-y-2">
        <div className="flex items-start gap-2 bg-white border border-[#E4E1D6] rounded-lg px-3 py-2.5">
          <ShieldCheck size={15} className="text-[#8A8578] mt-0.5 shrink-0" />
          <p className="text-[12px] text-[#4A4740]">
            <span className="font-medium text-[#1F1D19]">Assinatura digital real</span> — ligar o Termo de
            Responsabilidade e os relatórios à Chave Móvel Digital / Cartão de Cidadão. Precisa de integração
            com o sistema de autenticação.gov, feita depois de termos backend próprio.
          </p>
        </div>
        <div className="flex items-start gap-2 bg-white border border-[#E4E1D6] rounded-lg px-3 py-2.5">
          <WifiOff size={15} className="text-[#8A8578] mt-0.5 shrink-0" />
          <p className="text-[12px] text-[#4A4740]">
            <span className="font-medium text-[#1F1D19]">Modo offline em obra</span> — preencher checklists e
            tirar fotos sem rede, com sincronização automática ao voltar à cobertura. Implementa-se na app
            mobile com armazenamento local.
          </p>
        </div>
      </div>
    </>
  );
}

// ---------------------------------------------------------------------------
// App
// ---------------------------------------------------------------------------

export default function FiscalisDashboard() {
  const [nav, setNav] = useState("dashboard");
  const [obraAtiva, setObraAtiva] = useState(null);
  const [alertasAbertos, setAlertasAbertos] = useState(false);
  const alertasPrazo = NC_TODAS.filter((n) => n.estado !== "Fechada").slice(0, 4);

  const abrirObra = (obra) => {
    setObraAtiva(obra);
    setNav("obraDetalhe");
  };

  const irPara = (id) => {
    setObraAtiva(null);
    setNav(id);
  };

  return (
    <div className="w-full min-h-[780px] bg-[#F5F4EF] flex text-[#1F1D19]" style={{ fontFamily: "Inter, system-ui, sans-serif" }}>
      {/* Sidebar */}
      <aside className="w-[220px] shrink-0 flex flex-col bg-[#14283A]">
        <div className="flex items-center gap-2 px-5 py-6 border-b border-white/[0.06]">
          <img src={LOGO_SRC} alt="Fiscalis" className="h-8 w-auto" />
          <div className="leading-tight">
            <p className="text-white text-[13px] font-semibold tracking-wide">FISCALIS</p>
            <p className="text-[#C9A050] text-[9px] tracking-[0.15em] font-medium">ENGENHARIA</p>
          </div>
        </div>

        <nav className="flex-1 px-3 mt-3 space-y-0.5">
          {NAV.map((item) => {
            const Icon = item.icon;
            const active = item.id === nav || (item.id === "obras" && nav === "obraDetalhe");
            return (
              <button
                key={item.id}
                onClick={() => irPara(item.id)}
                className={`w-full flex items-center gap-2.5 px-3 py-2.5 rounded-lg text-[13px] transition-all duration-200 relative border ${
                  active
                    ? "text-[#F6EDD8]"
                    : "border-transparent text-[#9FB0BF] hover:text-white hover:bg-white/[0.04]"
                }`}
                style={
                  active
                    ? { backgroundColor: "rgba(201,160,80,0.16)", borderColor: "rgba(201,160,80,0.45)" }
                    : undefined
                }
              >
                {active && (
                  <span className="absolute left-0 top-1/2 -translate-y-1/2 w-[2.5px] h-4 bg-[#E9CE8F] rounded-r" />
                )}
                <Icon size={16} className={active ? "text-[#E9CE8F]" : ""} strokeWidth={active ? 2 : 1.75} />
                <span className={active ? "font-medium" : ""} style={active ? { letterSpacing: "0.01em" } : undefined}>
                  {item.label}
                </span>
              </button>
            );
          })}
        </nav>

        <div className="px-5 py-4 border-t border-white/10 relative">
          <p className="text-[11px] text-[#9FB0BF]">Pedro Melro</p>
          <p className="text-[10px] text-[#6E8294]">Eng.º Civil · Cédula 82160</p>
        </div>
      </aside>

      {/* Main */}
      <div className="flex-1 flex flex-col min-w-0">
        <div className="h-16 bg-white border-b border-[#E4E1D6] flex items-center justify-between px-6 shrink-0 shadow-[0_1px_3px_rgba(20,40,58,0.04)] relative z-10">
          <div className="flex items-center gap-2 text-[#8A8578] bg-[#F5F4EF] rounded-lg px-3 py-1.5 w-[280px]">
            <Search size={14} />
            <span className="text-[13px]">Pesquisar obras, clientes...</span>
          </div>
          <div className="flex items-center gap-4">
            <div className="relative">
              <button onClick={() => setAlertasAbertos((v) => !v)} className="relative text-[#4A4740]">
                <Bell size={18} />
                {alertasPrazo.length > 0 && (
                  <span className="absolute -top-1 -right-1 w-3.5 h-3.5 rounded-full bg-[#C4791E] text-white text-[9px] flex items-center justify-center">
                    {alertasPrazo.length}
                  </span>
                )}
              </button>
              {alertasAbertos && (
                <div className="absolute right-0 top-8 w-80 bg-white border border-[#E4E1D6] rounded-xl shadow-lg z-20 overflow-hidden">
                  <p className="text-[12px] font-medium text-[#4A4740] px-4 py-3 border-b border-[#EDEBE2]">
                    Prazos a aproximar-se
                  </p>
                  {alertasPrazo.map((n) => (
                    <div key={n.id} className="px-4 py-2.5 border-b border-[#F2F0E8] last:border-0">
                      <p className="text-[12px] text-[#1F1D19]">{n.descricao}</p>
                      <p className="text-[11px] text-[#8A8578] mt-0.5">
                        {n.obra} · prazo {n.prazo}
                      </p>
                    </div>
                  ))}
                </div>
              )}
            </div>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-full bg-[#14283A] text-white flex items-center justify-center text-[12px] font-medium">
                PM
              </div>
              <div className="leading-tight">
                <p className="text-[13px] font-medium">Pedro Melro</p>
                <p className="text-[11px] text-[#8A8578]">Fiscalis Engenharia</p>
              </div>
              <ChevronDown size={14} className="text-[#8A8578]" />
            </div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          {nav === "dashboard" && <DashboardView onOpenObra={abrirObra} />}
          {nav === "obras" && <ObrasView onOpenObra={abrirObra} />}
          {nav === "obraDetalhe" && obraAtiva && (
            <ObraDetalheView key={obraAtiva.id} obra={obraAtiva} onVoltar={() => irPara("obras")} />
          )}
          {nav === "visitas" && <VisitasView />}
          {nav === "calendario" && <CalendarioView />}
          {nav === "propostas" && <PropostasView />}
          {nav === "nc" && <NaoConformidadesView />}
          {nav === "documentos" && <DocumentosView />}
          {nav === "relatorios" && <RelatoriosView />}
          {nav === "portal" && <PortalClienteView />}
          {nav === "config" && <ConfiguracoesView />}
        </div>
      </div>
    </div>
  );
}
